<?php
session_start(); require __DIR__.'/db.php';
function e($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
function user(){return $_SESSION['user']??null;}
function go($u){header("Location: $u");exit;}
function need($role=null){if(!user())go('index.php?page=login');if($role&&user()['role']!==$role)go('index.php');}
function pageHead($title){?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> · SocietyCare</title><link rel="stylesheet" href="assets/style.css"></head><body><header><a class="brand" href="index.php">Society<span>Care</span></a><nav><?php if(user()):?><?php if(user()['role']==='resident'):?><a href="?page=resident">Dashboard</a><a href="?page=new">New Complaint</a><?php else:?><a href="?page=admin">Dashboard</a><a href="?page=staff">Staff</a><?php endif;?><a class="navbtn" href="?page=logout">Logout</a><?php else:?><a href="?page=login">Login</a><a class="navbtn" href="?page=register">Register</a><?php endif;?></nav></header><main class="wrap"><?php }
function foot(){?></main><footer>SocietyCare · Society Maintenance Management System</footer><script src="assets/app.js"></script></body></html><?php }

$page=$_GET['page']??'home';
