 if($_SERVER['REQUEST_METHOD']==='POST'){$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$role=$_POST['role']??'resident';$table=$role==='admin'?'admins':'residents';$stmt=$pdo->prepare("SELECT * FROM $table WHERE email=? LIMIT 1");$stmt->execute([$email]);$u=$stmt->fetch();if($u&&password_verify($pass,$u['password'])){$_SESSION['user']=['id'=>$role==='admin'?$u['admin_id']:$u['resident_id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$role];go('index.php?page='.($role==='admin'?'admin':'resident'));}$err='Invalid login details.';}
 pageHead('Login');?><section class="auth"><form class="card" method="post"><span class="eyebrow">Welcome back</span><h1>Login</h1><?php if($err):?><div class="alert bad"><?=e($err)?></div><?php endif;?><label>Account Type<select name="role"><option value="resident">Resident</option><option value="admin">Admin</option></select></label><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn primary">Login</button><p class="hint">Demo admin: admin@society.local / admin123</p></form></section><?php foot();exit;
}
if($page==='register'){
 if(user())go('index.php');$err='';
 if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['name']??'');$em=trim($_POST['email']??'');$ph=trim($_POST['phone']??'');$pw=$_POST['password']??'';$b=trim($_POST['building']??'');$f=trim($_POST['flat_no']??'');if(!$n||!filter_var($em,FILTER_VALIDATE_EMAIL)||strlen($pw)<6||!$b||!$f)$err='Please fill all required fields; password must be 6+ characters.';else try{$s=$pdo->prepare('INSERT INTO residents(name,email,phone,password,building,flat_no) VALUES(?,?,?,?,?,?)');$s->execute([$n,$em,$ph,password_hash($pw,PASSWORD_DEFAULT),$b,$f]);go('index.php?page=login');}catch(Exception $x){$err='Email is already registered.';}}
 pageHead('Register');?><section class="auth"><form class="card" method="post"><span class="eyebrow">Resident account</span><h1>Register</h1><?php if($err):?><div class="alert bad"><?=e($err)?></div><?php endif;?><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><div class="grid2"><label>Phone<input name="phone"></label><label>Password<input type="password" name="password" minlength="6" required></label></div><div class="grid2"><label>Building<input name="building" required></label><label>Flat No.<input name="flat_no" required></label></div><button class="btn primary">Create Account</button></form></section><?php foot();exit;
}
if($page==='new'){
 need('resident');$err='';
 if($_SERVER['REQUEST_METHOD']==='POST'){$cat=trim($_POST['category']??'');$title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$loc=trim($_POST['location']??'');$pri=$_POST['priority']??'Medium';$img=null;
  if(!$cat||!$title||!$desc||!$loc)$err='Complete all required fields.';
  if(!$err&&isset($_FILES['image'])&&$_FILES['image']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['image'];$mime=mime_content_type($f['tmp_name']);$map=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>MAX_UPLOAD||!isset($map[$mime]))$err='Image must be JPG, PNG or WEBP and max 5 MB.';else{$name=bin2hex(random_bytes(12)).'.'.$map[$mime];if(move_uploaded_file($f['tmp_name'],UPLOAD_DIR.$name))$img='uploads/'.$name;else $err='Could not save image.';}}
  if(!$err){$s=$pdo->prepare("INSERT INTO complaints(resident_id,category,title,description,location,priority,image_path,status) VALUES(?,?,?,?,?,?,?,'Submitted')");$s->execute([user()['id'],$cat,$title,$desc,$loc,$pri,$img]);$id=$pdo->lastInsertId();$s=$pdo->prepare('INSERT INTO status_history(complaint_id,status,remarks,updated_by) VALUES(?,?,?,?)');$s->execute([$id,'Submitted','Complaint received','Resident']);go('index.php?page=view&id='.$id);}}
 pageHead('New Complaint');?><section class="card wide"><span class="eyebrow">Maintenance request</span><h1>Submit Complaint</h1><?php if($err):?><div class="alert bad"><?=e($err)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><div class="grid2"><label>Category<select name="category" required><option value="">Select</option><option>Plumbing</option><option>Electrical</option><option>Lift</option><option>Cleaning</option><option>Security</option><option>Carpentry</option><option>Other</option></select></label><label>Priority<select name="priority"><option>Low</option><option selected>Medium</option><option>High</option></select></label></div><label>Title<input name="title" placeholder="e.g. Water leakage" required></label><label>Description<textarea name="description" rows="5" required></textarea></label><label>Location<input name="location" placeholder="Building A, Flat 302" required></label><label>Problem Image<input id="image" type="file" name="image" accept="image/jpeg,image/png,image/webp"><small>Optional · JPG/PNG/WEBP · max 5 MB</small></label><div id="preview"></div><button class="btn primary">Submit Complaint</button></form></section><?php foot();exit;
}
if($page==='resident'){
 need('resident');$s=$pdo->prepare('SELECT c.*,s.name staff_name FROM complaints c LEFT JOIN staff s ON c.staff_id=s.staff_id WHERE c.resident_id=? ORDER BY c.created_at DESC');$s->execute([user()['id']]);$rows=$s->fetchAll();pageHead('Resident Dashboard');?><div class="head"><div><span class="eyebrow">Resident portal</span><h1>Welcome, <?=e(user()['name'])?></h1><p>Track your maintenance complaints.</p></div><a class="btn primary" href="?page=new">+ New Complaint</a></div><div class="stats"><div><small>Total</small><b><?=count($rows)?></b></div><div><small>Submitted</small><b><?=count(array_filter($rows,fn($r)=>$r['status']==='Submitted'))?></b></div><div><small>In Progress</small><b><?=count(array_filter($rows,fn($r)=>$r['status']==='In Progress'))?></b></div><div><small>Resolved</small><b><?=count(array_filter($rows,fn($r)=>$r['status']==='Resolved'))?></b></div></div><section class="panel"><h2>My Complaints</h2><div class="table"><table><tr><th>ID</th><th>Complaint</th><th>Priority</th><th>Status</th><th>Staff</th><th></th></tr><?php foreach($rows as $r):?><tr><td>#<?=e($r['complaint_id'])?></td><td><b><?=e($r['title'])?></b><small><?=e($r['category'])?></small></td><td><?=e($r['priority'])?></td><td><span class="status <?=strtolower(str_replace(' ','-',$r['status']))?>"><?=e($r['status'])?></span></td><td><?=e($r['staff_name']??'Not assigned')?></td><td><a class="link" href="?page=view&id=<?=$r['complaint_id']?>">View</a></td></tr><?php endforeach;?></table></div></section><?php foot();exit;
}
if($page==='admin'){
 need('admin');$counts=$pdo->query("SELECT COUNT(*) total,SUM(status='Submitted') submitted,SUM(status='Assigned') assigned,SUM(status='In Progress') progress,SUM(status='Resolved') resolved FROM complaints")->fetch();$rows=$pdo->query('SELECT c.*,r.name resident,r.building,r.flat_no,s.name staff FROM complaints c JOIN residents r ON c.resident_id=r.resident_id LEFT JOIN staff s ON c.staff_id=s.staff_id ORDER BY c.created_at DESC')->fetchAll();pageHead('Admin Dashboard');?><div class="head"><div><span class="eyebrow">Administrator portal</span><h1>Society Overview</h1><p>Manage complaints and maintenance staff.</p></div><a class="btn secondary" href="?page=staff">Manage Staff</a></div><div class="stats"><div><small>Total</small><b><?=e($counts['total'])?></b></div><div><small>Submitted</small><b><?=e($counts['submitted'])?></b></div><div><small>Assigned</small><b><?=e($counts['assigned'])?></b></div><div><small>In Progress</small><b><?=e($counts['progress'])?></b></div><div><small>Resolved</small><b><?=e($counts['resolved'])?></b></div></div><section class="panel"><h2>All Complaints</h2><div class="table"><table><tr><th>ID</th><th>Resident</th><th>Complaint</th><th>Priority</th><th>Status</th><th>Staff</th><th></th></tr><?php foreach($rows as $r):?><tr><td>#<?=e($r['complaint_id'])?></td><td><b><?=e($r['resident'])?></b><small><?=e($r['building'].' - '.$r['flat_no'])?></small></td><td><b><?=e($r['title'])?></b><small><?=e($r['category'])?></small></td><td><?=e($r['priority'])?></td><td><span class="status <?=strtolower(str_replace(' ','-',$r['status']))?>"><?=e($r['status'])?></span></td><td><?=e($r['staff']??'Not assigned')?></td><td><a class="link" href="?page=view&id=<?=$r['complaint_id']?>">View</a></td></tr><?php endforeach;?></table></div></section><?php foot();exit;
}
if($page==='staff'){
 need('admin');$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['name']??'');$p=trim($_POST['phone']??'');$sp=trim($_POST['specialization']??'');if($n&&$sp){$s=$pdo->prepare("INSERT INTO staff(name,phone,specialization) VALUES(?,?,?)");$s->execute([$n,$p,$sp]);$msg='Staff member added.';}}$rows=$pdo->query('SELECT * FROM staff ORDER BY name')->fetchAll();pageHead('Staff');?><div class="head"><div><span class="eyebrow">Maintenance team</span><h1>Manage Staff</h1></div></div><div class="two"><form class="card" method="post"><h2>Add Staff</h2><?php if($msg):?><div class="alert good"><?=e($msg)?></div><?php endif;?><label>Name<input name="name" required></label><label>Phone<input name="phone"></label><label>Specialization<input name="specialization" placeholder="Plumber" required></label><button class="btn primary">Add Staff</button></form><section class="panel"><h2>Staff List</h2><div class="table"><table><tr><th>Name</th><th>Specialization</th><th>Phone</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['specialization'])?></td><td><?=e($r['phone'])?></td></tr><?php endforeach;?></table></div></section></div><?php foot();exit;
}
if($page==='update'){
 need('admin');$id=(int)$_GET['id'];$s=$pdo->prepare('SELECT * FROM complaints WHERE complaint_id=?');$s->execute([$id]);$c=$s->fetch();if(!$c)die('Not found');$staff=$pdo->query("SELECT * FROM staff WHERE status='Active' ORDER BY name")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){$sid=$_POST['staff_id']===''?null:(int)$_POST['staff_id'];$st=$_POST['status'];$remark=trim($_POST['remarks']??'');$s=$pdo->prepare('UPDATE complaints SET staff_id=?,status=?,updated_at=NOW() WHERE complaint_id=?');$s->execute([$sid,$st,$id]);if($st!==$_POST['old_status']||$remark){$s=$pdo->prepare('INSERT INTO status_history(complaint_id,status,remarks,updated_by) VALUES(?,?,?,?)');$s->execute([$id,$st,$remark?:'Complaint updated by Admin','Admin']);}go('?page=view&id='.$id);}pageHead('Manage Complaint');?><section class="card wide"><span class="eyebrow">Admin action</span><h1>Manage Complaint #<?=$id?></h1><form method="post"><input type="hidden" name="old_status" value="<?=e($c['status'])?>"><label>Assign Staff<select name="staff_id"><option value="">Not assigned</option><?php foreach($staff as $x):?><option value="<?=$x['staff_id']?>" <?=$c['staff_id']==$x['staff_id']?'selected':''?>><?=e($x['name'].' — '.$x['specialization'])?></option><?php endforeach;?></select></label><label>Status<select name="status"><?php foreach(['Submitted','Assigned','In Progress','Resolved'] as $st):?><option <?=$c['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select></label><label>Remarks<textarea name="remarks" rows="4"></textarea></label><button class="btn primary">Save Changes</button></form></section><?php foot();exit;
}
if($page==='feedback'){
 need('resident');$id=(int)$_POST['complaint_id'];$s=$pdo->prepare("SELECT * FROM complaints WHERE complaint_id=? AND resident_id=? AND status='Resolved'");$s->execute([$id,user()['id']]);if($s->fetch()&&($r=(int)$_POST['rating'])>=1&&$r<=5){$s=$pdo->prepare('INSERT INTO feedback(complaint_id,resident_id,rating,comments) VALUES(?,?,?,?)');$s->execute([$id,user()['id'],$r,trim($_POST['comments']??'')]);}go('?page=view&id='.$id);
}
if($page==='view'){
 need();$id=(int)$_GET['id'];if(user()['role']==='resident'){$s=$pdo->prepare('SELECT c.*,r.name resident,r.building,r.flat_no,s.name staff FROM complaints c JOIN residents r ON c.resident_id=r.resident_id LEFT JOIN staff s ON c.staff_id=s.staff_id WHERE c.complaint_id=? AND c.resident_id=?');$s->execute([$id,user()['id']]);}else{$s=$pdo->prepare('SELECT c.*,r.name resident,r.building,r.flat_no,s.name staff FROM complaints c JOIN residents r ON c.resident_id=r.resident_id LEFT JOIN staff s ON c.staff_id=s.staff_id WHERE c.complaint_id=?');$s->execute([$id]);}$c=$s->fetch();if(!$c)die('Complaint not found');$s=$pdo->prepare('SELECT * FROM status_history WHERE complaint_id=? ORDER BY updated_at,history_id');$s->execute([$id]);$hist=$s->fetchAll();$s=$pdo->prepare('SELECT * FROM feedback WHERE complaint_id=?');$s->execute([$id]);$fb=$s->fetch();pageHead('Complaint #'.$id);?><div class="head"><div><span class="eyebrow">Complaint #<?=$id?></span><h1><?=e($c['title'])?></h1><p><?=e($c['category'].' · '.$c['location'])?></p></div><span class="status large <?=strtolower(str_replace(' ','-',$c['status']))?>"><?=e($c['status'])?></span></div><div class="two"><section class="panel"><h2>Complaint Details</h2><p><b>Resident:</b> <?=e($c['resident'])?></p><p><b>Flat:</b> <?=e($c['building'].' - '.$c['flat_no'])?></p><p><b>Priority:</b> <?=e($c['priority'])?></p><p><b>Staff:</b> <?=e($c['staff']??'Not assigned')?></p><p><b>Description:</b><br><?=nl2br(e($c['description']))?></p><?php if($c['image_path']):?><h3>Uploaded Image</h3><img class="complaint-img" src="<?=e($c['image_path'])?>" alt="Complaint image"><?php endif;?></section><section class="panel"><h2>Status History</h2><?php foreach($hist as $h):?><div class="history"><b><?=e($h['status'])?></b><p><?=e($h['remarks'])?></p><small><?=e(date('d M Y, h:i A',strtotime($h['updated_at'])))?> · <?=e($h['updated_by'])?></small></div><?php endforeach;?></section></div><?php if(user()['role']==='admin'):?><section class="panel"><a class="btn primary" href="?page=update&id=<?=$id?>">Manage Complaint</a></section><?php elseif($c['status']==='Resolved'&&!$fb):?><section class="card"><h2>Give Feedback</h2><form method="post" action="?page=feedback"><input type="hidden" name="complaint_id" value="<?=$id?>"><label>Rating<select name="rating" required><option value="">Select</option><option>5</option><option>4</option><option>3</option><option>2</option><option>1</option></select></label><label>Comments<textarea name="comments" rows="3"></textarea></label><button class="btn primary">Submit Feedback</button></form></section><?php elseif($fb):?><section class="panel"><h2>Feedback</h2><p>★ <?=e($fb['rating'])?>/5</p><p><?=nl2br(e($fb['comments']))?></p></section><?php endif;?><?php foot();exit;
}
